W() {
        // To find out if the text is overflowing, we will disable wrapping, check the widths, and then re-enable wrapping
        this.w.containerDomNode.style.setProperty('--vscode-hover-whiteSpace', 'nowrap');
        this.w.containerDomNode.style.setProperty('--vscode-hover-sourceWhiteSpace', 'nowrap');
        const overflowing = Array.from(this.w.contentsDomNode.children).some((hoverElement) => {
            return hoverElement.scrollWidth > hoverElement.clientWidth;
        });
        this.w.containerDomNode.style.removeProperty('--vscode-hover-whiteSpace');
        this.w.containerDomNode.style.removeProperty('--vscode-hover-sourceWhiteSpace');
        return overflowing;
    }
